quarterly_testing_budget = {
    "checkout": 0.15,    # 15% of monthly budget
    "search": 0.10,       # 10%
    "recommendations": 0.08,  # 8%
}

def approve_experiment(team, duration_days, traffic_pct):
    budget = quarterly_testing_budget.get(team, 0)
    cost = (duration_days / 90) * (traffic_pct / 100) * budget
    return cost < budget * 0.5  # Allow if under 50% of budget
